"""

from __future__ import annotations

import copy
import sys
from collections import defaultdict

from program_model import (
    ClassDef,
    Method,
    MethodSignature,
    Program,
    Statement,
    load_all_benchmarks,
)
from utils import (
    Timer,
    build_hierarchy,
    get_all_subclasses,
)

# Kinds of statements that never define a local we may eliminate and
# always carry observable behaviour for the DCE pass.
_SIDE_EFFECT_KINDS = {"call", "return", "if", "field_store", "identity"}


def is_constant_value(value: str | None) -> bool:
    """Return True when ``value`` denotes a constant rather than a local."""
    if value is None:
        return True
    if value in {"null", "true", "false"}:
        return True
    if value.startswith('"'):
        return True
    try:
        float(value)
        return True
    except ValueError:
        return False


def used_locals(stmt: Statement) -> set[str]:
    """All locals read by a statement."""
    used = {v for v in stmt.rhs_vars if not is_constant_value(v)}
    for arg in stmt.args:
        if not is_constant_value(arg):
            used.add(arg)
    if stmt.receiver and not is_constant_value(stmt.receiver):
        used.add(stmt.receiver)
    if stmt.field_ref and not is_constant_value(stmt.field_ref.base):
        used.add(stmt.field_ref.base)
    if stmt.kind == "return" and stmt.rhs and not is_constant_value(stmt.rhs):
        used.add(stmt.rhs)
    if stmt.kind == "assign" and stmt.rhs and not is_constant_value(stmt.rhs):
        used.add(stmt.rhs)
    return used


# ---------------------------------------------------------------------------
# Jimple-like IR
# ---------------------------------------------------------------------------


class JimpleBody:
    """A Jimple-like view over a :class:`MethodBody`.

    Units are indexed in layout order; ``successors`` computes the
    intraprocedural control-flow successors of a unit.
    """

    def __init__(self, method: Method):
        self.method = method
        body = method.body
        self.locals = list(body.locals) if body else []
        self.units: list[Statement] = list(body.statements) if body else []
        self.this_local = body.this_local if body else None
        self.param_locals = list(body.param_locals) if body else []
        self.trap_handlers = list(body.trap_handlers) if body else []
        self._index_by_id = {s.stmt_id: i for i, s in enumerate(self.units)}

    def __len__(self) -> int:
        return len(self.units)

    def stmt_index(self, stmt_id: int) -> int | None:
        return self._index_by_id.get(stmt_id)

    def get_unit(self, stmt_id: int) -> Statement | None:
        idx = self._index_by_id.get(stmt_id)
        return self.units[idx] if idx is not None else None

    def successors(self, index: int) -> list[int]:
        stmt = self.units[index]
        if stmt.kind == "return":
            return []
        if stmt.kind == "if":
            out = []
            for target in (stmt.true_target, stmt.false_target):
                idx = self._index_by_id.get(target) if target is not None else None
                if idx is not None:
                    out.append(idx)
            if not out and index + 1 < len(self.units):
                out.append(index + 1)
            return out
        return [index + 1] if index + 1 < len(self.units) else []


# ---------------------------------------------------------------------------
# Scene registry
# ---------------------------------------------------------------------------


class Scene:
    """Whole-program registry: classes, methods, hierarchy, entry points."""

    def __init__(self):
        self.program: Program | None = None
        self.classes: dict[str, ClassDef] = {}
        self.methods: dict[str, tuple[ClassDef, Method]] = {}
        self.hierarchy: dict[str, list[str]] = {}
        self.entry_points: list[Method] = []

    def load_program(self, program: Program) -> "Scene":
        self.program = program
        self.classes = {c.name: c for c in program.classes}
        self.methods = {}
        for cls in program.classes:
            for method in cls.methods:
                self.methods[method.signature.full_signature()] = (cls, method)
        self.hierarchy = build_hierarchy(program)
        self.entry_points = self._collect_entry_points(program)
        return self

    # -- queries ----------------------------------------------------------

    def get_class(self, name: str) -> ClassDef | None:
        return self.classes.get(name)

    def get_method(self, full_signature: str) -> Method | None:
        entry = self.methods.get(full_signature)
        return entry[1] if entry else None

    def get_method_class(self, method: Method) -> ClassDef | None:
        return self.classes.get(method.signature.class_name)

    def all_methods(self) -> list[Method]:
        return [m for _, m in self.methods.values()]

    def methods_with_bodies(self) -> list[Method]:
        return [m for m in self.all_methods() if m.body is not None]

    def get_subclasses(self, class_name: str) -> set[str]:
        return get_all_subclasses(self.hierarchy, class_name)

    def _collect_entry_points(self, program: Program) -> list[Method]:
        entries: list[Method] = []
        seen: set[str] = set()
        for sig in program.entry_points:
            method = self.get_method(sig.full_signature())
            if method and method.signature.full_signature() not in seen:
                seen.add(method.signature.full_signature())
                entries.append(method)
        for cls in program.classes:
            for method in cls.methods:
                if method.is_entry_point and method.signature.full_signature() not in seen:
                    seen.add(method.signature.full_signature())
                    entries.append(method)
        return entries

    # -- resolution ---------------------------------------------------------

    def lookup_method(
        self, class_name: str, method_name: str, arity: int
    ) -> Method | None:
        """Upward (superclass-chain) lookup of a method by name and arity."""
        seen: set[str] = set()
        current: str | None = class_name
        while current and current not in seen:
            seen.add(current)
            cls = self.classes.get(current)
            if cls is None:
                break
            for method in cls.methods:
                sig = method.signature
                if sig.method_name == method_name and len(sig.param_types) == arity:
                    return method
            current = cls.super_class
        return None

    def resolve_cha(self, callee: MethodSignature) -> list[Method]:
        """Class-hierarchy analysis resolution of a call target.

        The primary target is found in the declared receiver class (or
        inherited from a super class); every known subclass that
        overrides the method is an additional potential target.
        """
        targets: list[Method] = []
        seen: set[str] = set()
        arity = len(callee.param_types)
        primary = self.lookup_method(callee.class_name, callee.method_name, arity)
        if primary is not None:
            targets.append(primary)
            seen.add(primary.signature.full_signature())
        for sub in sorted(self.get_subclasses(callee.class_name)):
            cls = self.classes.get(sub)
            if cls is None:
                continue
            for method in cls.methods:
                sig = method.signature
                if (
                    sig.method_name == callee.method_name
                    and len(sig.param_types) == arity
                    and sig.full_signature() not in seen
                ):
                    seen.add(sig.full_signature())
                    targets.append(method)
        return targets


# ---------------------------------------------------------------------------
# CHA call graph
# ---------------------------------------------------------------------------


class CallGraph:
    """A call graph over full method signatures.

    Edges are ``(caller_signature, call_stmt_id, callee_signature)``.
    """

    def __init__(self):
        self.edges: set[tuple[str, int, str]] = set()
        self._out: dict[str, set[str]] = defaultdict(set)
        self._into: dict[str, set[str]] = defaultdict(set)

    def add_edge(self, caller: str, call_stmt_id: int, callee: str) -> None:
        edge = (caller, call_stmt_id, callee)
        if edge in self.edges:
            return
        self.edges.add(edge)
        self._out[caller].add(callee)
        self._into[callee].add(caller)

    def __len__(self) -> int:
        return len(self.edges)

    def nodes(self) -> set[str]:
        return set(self._out) | set(self._into)

    def callees_of(self, caller: str) -> set[str]:
        return set(self._out.get(caller, ()))

    def callers_of(self, callee: str) -> set[str]:
        return set(self._into.get(callee, ()))

    def edges_out_of(self, caller: str) -> list[tuple[str, int, str]]:
        return sorted(e for e in self.edges if e[0] == caller)

    def edges_into(self, callee: str) -> list[tuple[str, int, str]]:
        return sorted(e for e in self.edges if e[2] == callee)


class CHACallGraphBuilder:
    """Builds a call graph by class-hierarchy analysis from entry points."""

    def __init__(self, scene: Scene):
        self.scene = scene

    def build(self) -> CallGraph:
        graph = CallGraph()
        reachable: set[str] = set()
        worklist = [m.signature.full_signature() for m in self.scene.entry_points]
        while worklist:
            caller_sig = worklist.pop()
            if caller_sig in reachable:
                continue
            reachable.add(caller_sig)
            method = self.scene.get_method(caller_sig)
            if method is None or method.body is None:
                continue
            for stmt in method.body.statements:
                if stmt.kind != "call" or stmt.callee is None:
                    continue
                for target in self.scene.resolve_cha(stmt.callee):
                    target_sig = target.signature.full_signature()
                    graph.add_edge(caller_sig, stmt.stmt_id, target_sig)
                    if target_sig not in reachable:
                        worklist.append(target_sig)
        self.reachable_methods = reachable
        return graph


# ---------------------------------------------------------------------------
# Copy propagation
# ---------------------------------------------------------------------------


def _replace_in_statement(stmt: Statement, old: str, new: str) -> int:
    """Replace uses of local ``old`` by ``new`` in ``stmt``; return count."""
    count = 0
    if stmt.rhs == old:
        stmt.rhs = new
        count += 1
    for i, var in enumerate(stmt.rhs_vars):
        if var == old:
            stmt.rhs_vars[i] = new
            count += 1
    for i, arg in enumerate(stmt.args):
        if arg == old:
            stmt.args[i] = new
            count += 1
    if stmt.receiver == old:
        stmt.receiver = new
        count += 1
    if stmt.field_ref is not None and stmt.field_ref.base == old:
        stmt.field_ref.base = new
        count += 1
    if stmt.condition is not None and old in stmt.condition:
        stmt.condition = stmt.condition.replace(old, new)
        count += 1
    return count


class CopyPropagator:
    """Propagates copies ``x = y`` forward until ``x`` or ``y`` is killed."""

    def is_copy(self, stmt: Statement) -> bool:
        return (
            stmt.kind == "assign"
            and stmt.lhs is not None
            and stmt.rhs is not None
            and len(stmt.rhs_vars) == 1
            and stmt.rhs_vars[0] == stmt.rhs
            and not is_constant_value(stmt.rhs)
        )

    def run(self, body: JimpleBody) -> int:
        """Propagate all copies in ``body``; return number of replaced uses."""
        replacements = 0
        units = body.units
        for i, stmt in enumerate(units):
            if not self.is_copy(stmt):
                continue
            src, dst = stmt.rhs, stmt.lhs
            for j in range(i + 1, len(units)):
                later = units[j]
                if later.lhs in (dst, src):
                    break  # either variable is redefined: stop propagating
                replacements += _replace_in_statement(later, dst, src)
        return replacements


# ---------------------------------------------------------------------------
# Dead-code elimination
# ---------------------------------------------------------------------------


class DeadCodeEliminator:
    """Removes side-effect-free statements defining dead locals."""

    def _compute_live_out(self, body: JimpleBody) -> list[set[str]]:
        n = len(body.units)
        uses = [used_locals(s) for s in body.units]
        defs = [{s.lhs} if s.lhs else set() for s in body.units]
        live_in = [set() for _ in range(n)]
        live_out = [set() for _ in range(n)]
        changed = True
        while changed:
            changed = False
            for i in range(n - 1, -1, -1):
                out: set[str] = set()
                for succ in body.successors(i):
                    out |= live_in[succ]
                new_in = uses[i] | (out - defs[i])
                if new_in != live_in[i] or out != live_out[i]:
                    live_in[i] = new_in
                    live_out[i] = out
                    changed = True
        return live_out

    def _removable(self, stmt: Statement, live_out: set[str]) -> bool:
        if stmt.kind in _SIDE_EFFECT_KINDS or stmt.is_source or stmt.is_sink:
            return False
        if stmt.kind == "nop":
            return True
        if stmt.kind in ("assign", "new"):
            return stmt.lhs is None or stmt.lhs not in live_out
        return False

    def run(self, body: JimpleBody) -> int:
        """Eliminate dead statements from ``body``; return removal count."""
        removed = 0
        while True:
            live_out = self._compute_live_out(body)
            victims = [
                i
                for i, stmt in enumerate(body.units)
                if self._removable(stmt, live_out[i])
            ]
            if not victims:
                break
            removed += len(victims)
            body.units = [s for i, s in enumerate(body.units) if i not in set(victims)]
            body._index_by_id = {s.stmt_id: i for i, s in enumerate(body.units)}
        if body.method.body is not None:
            body.method.body.statements = list(body.units)
        return removed


# ---------------------------------------------------------------------------
# Whole-program driver
# ---------------------------------------------------------------------------


def analyze_program(program: Program) -> dict:
    """Run the full Soot-style layer over one program; return statistics."""
    scene = Scene().load_program(program)
    builder = CHACallGraphBuilder(scene)
    call_graph = builder.build()

    n_statements = 0
    copy_propagations = 0
    dead_removed = 0
    propagator = CopyPropagator()
    eliminator = DeadCodeEliminator()
    for method in scene.methods_with_bodies():
        # Optimizations operate on a deep copy: the analysis layers above
        # this one consume the unmodified IR.
        optimized = copy.deepcopy(method)
        body = JimpleBody(optimized)
        n_statements += len(body)
        copy_propagations += propagator.run(body)
        dead_removed += eliminator.run(body)

    return {
        "name": program.name,
        "scene": scene,
        "call_graph": call_graph,
        "classes": len(scene.classes),
        "methods": len(scene.all_methods()),
        "statements": n_statements,
        "entry_points": len(scene.entry_points),
        "call_graph_edges": len(call_graph),
        "reachable_methods": len(builder.reachable_methods),
        "copy_propagations": copy_propagations,
        "dead_statements_removed": dead_removed,
    }


def main(argv: list[str]) -> int:
    benchmark_dir = argv[1] if len(argv) > 1 else "benchmarks"
    programs = load_all_benchmarks(benchmark_dir)

    print("LAYER: soot")
    totals = defaultdict(int)
    with Timer() as timer:
        for program in programs:
            stats = analyze_program(program)
            print(f"BENCHMARK: {stats['name']}")
            print(f"CLASSES: {stats['classes']}")
            print(f"METHODS: {stats['methods']}")
            print(f"STATEMENTS: {stats['statements']}")
            print(f"ENTRY_POINTS: {stats['entry_points']}")
            print(f"CALL_GRAPH_EDGES: {stats['call_graph_edges']}")
            print(f"REACHABLE_METHODS: {stats['reachable_methods']}")
            print(f"COPY_PROPAGATIONS: {stats['copy_propagations']}")
            print(f"DEAD_STATEMENTS_REMOVED: {stats['dead_statements_removed']}")
            for key in (
                "classes",
                "methods",
                "statements",
                "entry_points",
                "call_graph_edges",
                "reachable_methods",
                "copy_propagations",
                "dead_statements_removed",
            ):
                totals[key] += stats[key]
            totals["benchmarks"] += 1

    print(f"TOTAL_BENCHMARKS: {totals['benchmarks']}")
    print(f"TOTAL_CLASSES: {totals['classes']}")
    print(f"TOTAL_METHODS: {totals['methods']}")
    print(f"TOTAL_STATEMENTS: {totals['statements']}")
    print(f"TOTAL_CALL_GRAPH_EDGES: {totals['call_graph_edges']}")
    print(f"TOTAL_REACHABLE_METHODS: {totals['reachable_methods']}")
    print(f"TOTAL_COPY_PROPAGATIONS: {totals['copy_propagations']}")
    print(f"TOTAL_DEAD_STATEMENTS_REMOVED: {totals['dead_statements_removed']}")
    print(f"ANALYSIS_TIME_MS: {timer.elapsed_ms:.2f}")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

