"""
flowdroid_analysis.py -- FlowDroid-style IFDS taint analysis.

Layer 2 of the static-analysis stack, built on top of the Soot layer
(:mod:`soot_analysis`). Provides:

* access paths (:class:`AccessPath`) and taint facts
  (:class:`TaintFact`) carrying their originating source,
* source/sink handling driven both by statement flags and by the
  program's ``source_sink_spec`` (:class:`SourceSinkManager`),
* an IFDS-style forward taint solver (:class:`IFDSTaintAnalysis`) over
  the interprocedural supergraph induced by the CHA call graph, with
  flow-sensitive intraprocedural propagation, field sensitivity,
  on-demand interprocedural summaries and context memoization,
* alias support through flow-insensitive local alias groups, and
* lifecycle-aware propagation: taint stored into Android component
  fields in one entry point (e.g. ``onCreate``) becomes visible in
  every other lifecycle entry point (e.g. ``onResume``) via a
  whole-program fixpoint over shared component field state.

Calls that cannot be resolved to an application method body (native
code, opaque library code) are handled by a conservative default taint
wrapper: taint on any argument or on the receiver propagates to the
call's return value and to the receiver object.

Runs standalone::

    python3 flowdroid_analysis.py [benchmark_dir]

and emits ``KEY: VALUE`` experiment lines per benchmark plus aggregate
precision/recall statistics.
"""

from __future__ import annotations

import sys
from dataclasses import dataclass, field

from program_model import ClassDef, Method, Program, Statement, load_all_benchmarks
from soot_analysis import JimpleBody, Scene, is_constant_value
from utils import Timer


# ---------------------------------------------------------------------------
# Taint facts
# ---------------------------------------------------------------------------


@dataclass(frozen=True)
class AccessPath:
    """A tainted access path: a base local plus a sequence of fields."""

    base: str
    fields: tuple[str, ...] = ()

    def __str__(self) -> str:
        if self.fields:
            return f"{self.base}." + ".".join(self.fields)
        return self.base


@dataclass(frozen=True)
class SourceInfo:
    """Describes the source a taint fact originates from."""

    method: str
    category: str
    stmt_id: int


@dataclass(frozen=True)
class TaintFact:
    """An IFDS dataflow fact: a tainted access path plus its origin."""

    path: AccessPath
    source: SourceInfo

    def __str__(self) -> str:
        return f"{self.path} <{self.source.method}/{self.source.category}>"


@dataclass
class TaintLeak:
    """A detected source-to-sink flow."""

    source_method: str
    source_category: str
    sink_method: str
    sink_category: str
    sink_stmt_id: int
    sink_context: str  # full signature of the method containing the sink
    tainted_var: str
    path: str

    def key(self) -> tuple:
        return (
            self.source_method,
            self.source_category,
            self.sink_method,
            self.sink_stmt_id,
            self.sink_context,
            self.tainted_var,
        )


@dataclass
class MethodResult:
    """Summary of one analyzed method invocation context."""

    signature: str
    return_facts: set[TaintFact] = field(default_factory=set)
    exit_facts: set[TaintFact] = field(default_factory=set)


# ---------------------------------------------------------------------------
# Source/sink management
# ---------------------------------------------------------------------------


class SourceSinkManager:
    """Resolves sources and sinks from statement flags and the spec."""

    def __init__(self, spec: dict):
        self.sources = {
            (s["class_name"], s["method_name"]): s.get("category", "UNKNOWN")
            for s in spec.get("sources", [])
        }
        self.sinks = {
            (s["class_name"], s["method_name"]): s.get("category", "UNKNOWN")
            for s in spec.get("sinks", [])
        }

    def source_category(self, stmt: Statement) -> str | None:
        key = (stmt.callee.class_name, stmt.callee.method_name) if stmt.callee else None
        if stmt.is_source:
            return stmt.source_category or self.sources.get(key, "UNKNOWN")
        if key is not None and key in self.sources:
            return self.sources[key]
        return None

    def sink_category(self, stmt: Statement) -> str | None:
        key = (stmt.callee.class_name, stmt.callee.method_name) if stmt.callee else None
        if stmt.is_sink:
            return stmt.sink_category or self.sinks.get(key, "UNKNOWN")
        if key is not None and key in self.sinks:
            return self.sinks[key]
        return None


# ---------------------------------------------------------------------------
# Alias support
# ---------------------------------------------------------------------------


class AliasGroups:
    """Flow-insensitive union-find over the locals of one method body.

    Copy assignments ``x = y`` make ``x`` and ``y`` aliases: tainting a
    field of one must be visible through the other.
    """

    def __init__(self, body: JimpleBody):
        self.parent = {v.name: v.name for v in body.locals}
        for stmt in body.units:
            if (
                stmt.kind == "assign"
                and stmt.lhs
                and len(stmt.rhs_vars) == 1
                and stmt.rhs_vars[0] == stmt.rhs
                and stmt.rhs in self.parent
                and stmt.lhs in self.parent
            ):
                self.union(stmt.lhs, stmt.rhs)

    def find(self, x: str) -> str:
        root = x
        while self.parent.get(root, root) != root:
            root = self.parent[root]
        while self.parent.get(x, x) != root:
            self.parent[x], x = root, self.parent.get(x, x)
        return root

    def union(self, a: str, b: str) -> None:
        ra, rb = self.find(a), self.find(b)
        if ra != rb:
            self.parent[max(ra, rb)] = min(ra, rb)

    def group_of(self, base: str) -> set[str]:
        root = self.find(base)
        return {v for v in self.parent if self.find(v) == root} or {base}

    def same_object(self, a: str, b: str) -> bool:
        return self.find(a) == self.find(b)


# ---------------------------------------------------------------------------
# IFDS taint solver
# ---------------------------------------------------------------------------


class IFDSTaintAnalysis:
    """FlowDroid-style IFDS solver over the CHA-based supergraph."""

    def __init__(self, program: Program):
        self.program = program
        self.scene = Scene().load_program(program)
        self.sources_sinks = SourceSinkManager(program.source_sink_spec)
        self.leaks: list[TaintLeak] = []
        self._leak_keys: set[tuple] = set()
        # Shared component field state: (class, field) -> originating sources.
        self.global_field_taint: dict[tuple[str, str], set[SourceInfo]] = {}
        self._memo: dict[tuple, MethodResult] = {}
        self._active: set[tuple] = set()
        self.facts_generated = 0
        self.methods_analyzed = 0
        self.max_rounds = 10

    # -- driver ------------------------------------------------------------

    def run(self) -> "IFDSTaintAnalysis":
        """Analyze all entry points to a lifecycle-aware fixpoint."""
        previous = None
        for _ in range(self.max_rounds):
            self._memo.clear()  # global field state may have changed
            for method in self.scene.entry_points:
                cls = self.scene.get_method_class(method)
                self._analyze_method(cls, method, frozenset())
            current = (
                frozenset(self._leak_keys),
                frozenset(
                    (k, frozenset(v)) for k, v in self.global_field_taint.items()
                ),
            )
            if current == previous:
                break
            previous = current
        return self

    # -- fact helpers --------------------------------------------------------

    def _add_fact(
        self, factset: set[TaintFact], fact: TaintFact, aliases: AliasGroups
    ) -> None:
        """Add a fact plus its alias-rebased variants to ``factset``."""
        for base in aliases.group_of(fact.path.base):
            factset.add(TaintFact(AccessPath(base, fact.path.fields), fact.source))
            self.facts_generated += 1

    def _facts_on(
        self, facts: set[TaintFact], var: str, aliases: AliasGroups
    ) -> list[TaintFact]:
        return [f for f in facts if aliases.same_object(f.path.base, var)]

    # -- interprocedural machinery ------------------------------------------

    def _memo_key(self, method: Method, seed_facts: frozenset) -> tuple:
        normalized = frozenset(
            (f.path.base, f.path.fields, f.source.method, f.source.category)
            for f in seed_facts
        )
        return (method.signature.full_signature(), normalized)

    def _analyze_method(
        self, cls: ClassDef | None, method: Method, seed_facts: frozenset
    ) -> MethodResult:
        key = self._memo_key(method, seed_facts)
        if key in self._memo:
            return self._memo[key]
        if key in self._active:
            return MethodResult(method.signature.full_signature())
        if method.body is None:
            return MethodResult(method.signature.full_signature())
        self._active.add(key)
        try:
            result = self._analyze_body(cls, method, set(seed_facts))
        finally:
            self._active.discard(key)
        self._memo[key] = result
        return result

    def _follow_target(self, method: Method) -> bool:
        """Whether calls to ``method`` are followed interprocedurally."""
        cls = self.scene.get_method_class(method)
        return cls is not None and not cls.is_library

    def _analyze_body(
        self, cls: ClassDef | None, method: Method, seeds: set[TaintFact]
    ) -> MethodResult:
        body = JimpleBody(method)
        aliases = AliasGroups(body)
        self.methods_analyzed += 1

        # Lifecycle bridge: taint previously stored into component fields
        # (possibly in another entry point) is visible on `this`.
        if body.this_local:
            for (cname, fname), srcs in self.global_field_taint.items():
                if cname == method.signature.class_name:
                    for src in srcs:
                        self._add_fact(
                            seeds,
                            TaintFact(AccessPath(body.this_local, (fname,)), src),
                            aliases,
                        )

        n = len(body)
        in_sets: list[set[TaintFact]] = [set() for _ in range(n)]
        worklist: list[int] = []
        if n:
            in_sets[0] = set(seeds)
            worklist.append(0)

        result = MethodResult(method.signature.full_signature())
        while worklist:
            idx = worklist.pop()
            stmt = body.units[idx]
            out = self._transfer(stmt, in_sets[idx], body, aliases, method)
            if stmt.kind == "return":
                result.exit_facts |= in_sets[idx]
                if stmt.rhs and not is_constant_value(stmt.rhs):
                    for fact in self._facts_on(in_sets[idx], stmt.rhs, aliases):
                        result.return_facts.add(
                            TaintFact(AccessPath("@return", fact.path.fields), fact.source)
                        )
            for succ in body.successors(idx):
                if not out <= in_sets[succ]:
                    in_sets[succ] |= out
                    if succ not in worklist:
                        worklist.append(succ)
        return result

    # -- flow functions -------------------------------------------------------

    def _transfer(
        self,
        stmt: Statement,
        facts: set[TaintFact],
        body: JimpleBody,
        aliases: AliasGroups,
        method: Method,
    ) -> set[TaintFact]:
        kind = stmt.kind
        if kind == "call":
            return self._transfer_call(stmt, facts, aliases)
        out = set(facts)
        if kind == "assign":
            out = {f for f in out if not aliases.same_object(f.path.base, stmt.lhs)}
            if stmt.rhs and not is_constant_value(stmt.rhs):
                for fact in self._facts_on(facts, stmt.rhs, aliases):
                    self._add_fact(
                        out, TaintFact(AccessPath(stmt.lhs, fact.path.fields), fact.source),
                        aliases,
                    )
        elif kind == "new":
            out = {f for f in out if not aliases.same_object(f.path.base, stmt.lhs)}
        elif kind == "field_store":
            ref = stmt.field_ref
            stored = [v for v in stmt.rhs_vars if not is_constant_value(v)]
            if ref is not None and stored:
                for fact in self._facts_on(facts, stored[0], aliases):
                    self._add_fact(
                        out,
                        TaintFact(AccessPath(ref.base, (ref.field_name,)), fact.source),
                        aliases,
                    )
                    self.global_field_taint.setdefault(
                        (ref.declaring_class, ref.field_name), set()
                    ).add(fact.source)
        elif kind == "field_load":
            ref = stmt.field_ref
            out = {f for f in out if not aliases.same_object(f.path.base, stmt.lhs)}
            if ref is not None:
                for fact in self._facts_on(facts, ref.base, aliases):
                    if fact.path.fields and fact.path.fields[0] == ref.field_name:
                        self._add_fact(
                            out,
                            TaintFact(
                                AccessPath(stmt.lhs, fact.path.fields[1:]), fact.source
                            ),
                            aliases,
                        )
                    elif not fact.path.fields:
                        # The whole object is tainted: any field read is.
                        self._add_fact(
                            out, TaintFact(AccessPath(stmt.lhs, ()), fact.source), aliases
                        )
                for src in self.global_field_taint.get(
                    (ref.declaring_class, ref.field_name), ()
                ):
                    self._add_fact(
                        out, TaintFact(AccessPath(stmt.lhs, ()), src), aliases
                    )
        return out

    def _transfer_call(
        self, stmt: Statement, facts: set[TaintFact], aliases: AliasGroups
    ) -> set[TaintFact]:
        ssm = self.sources_sinks
        out = set(facts)
        if stmt.lhs:
            out = {f for f in out if not aliases.same_object(f.path.base, stmt.lhs)}

        # --- sources ------------------------------------------------------
        source_category = ssm.source_category(stmt)
        if source_category is not None and stmt.lhs:
            src = SourceInfo(stmt.callee.method_name, source_category, stmt.stmt_id)
            self._add_fact(out, TaintFact(AccessPath(stmt.lhs, ()), src), aliases)

        # --- sinks ----------------------------------------------------------
        sink_category = ssm.sink_category(stmt)
        if sink_category is not None:
            for arg in stmt.args:
                if is_constant_value(arg):
                    continue
                for fact in self._facts_on(facts, arg, aliases):
                    self._record_leak(
                        TaintLeak(
                            source_method=fact.source.method,
                            source_category=fact.source.category,
                            sink_method=stmt.callee.method_name,
                            sink_category=sink_category,
                            sink_stmt_id=stmt.stmt_id,
                            sink_context=self._current_context,
                            tainted_var=arg,
                            path=str(fact.path),
                        )
                    )

        # --- propagation ----------------------------------------------------
        if source_category is not None:
            return out  # precise source fact already generated
        if not self._propagate_interprocedural(stmt, facts, out, aliases):
            self._apply_opaque_call(stmt, facts, out, aliases)
        return out

    _current_context: str = ""

    def _propagate_interprocedural(
        self,
        stmt: Statement,
        facts: set[TaintFact],
        out: set[TaintFact],
        aliases: AliasGroups,
    ) -> bool:
        """Follow resolvable application calls; return True when followed."""
        targets = [
            t
            for t in self.scene.resolve_cha(stmt.callee)
            if t.body is not None and self._follow_target(t)
        ]
        if not targets:
            return False
        caller_aliases = aliases
        for target in targets:
            tbody = target.body
            seeds: set[TaintFact] = set()
            for i, arg in enumerate(stmt.args):
                if is_constant_value(arg) or i >= len(tbody.param_locals):
                    continue
                for fact in self._facts_on(facts, arg, caller_aliases):
                    seeds.add(
                        TaintFact(
                            AccessPath(tbody.param_locals[i], fact.path.fields),
                            fact.source,
                        )
                    )
            if stmt.receiver and tbody.this_local:
                for fact in self._facts_on(facts, stmt.receiver, caller_aliases):
                    seeds.add(
                        TaintFact(
                            AccessPath(tbody.this_local, fact.path.fields), fact.source
                        )
                    )
            tcls = self.scene.get_method_class(target)
            saved, self._current_context = (
                self._current_context,
                target.signature.full_signature(),
            )
            result = self._analyze_method(tcls, target, frozenset(seeds))
            self._current_context = saved
            if stmt.lhs:
                for fact in result.return_facts:
                    self._add_fact(
                        out,
                        TaintFact(AccessPath(stmt.lhs, fact.path.fields), fact.source),
                        caller_aliases,
                    )
            # Write taint placed on the callee's `this` back to the receiver.
            if stmt.receiver and tbody.this_local:
                for fact in result.exit_facts:
                    if fact.path.base == tbody.this_local:
                        self._add_fact(
                            out,
                            TaintFact(
                                AccessPath(stmt.receiver, fact.path.fields), fact.source
                            ),
                            caller_aliases,
                        )
        return True

    def _apply_opaque_call(
        self,
        stmt: Statement,
        facts: set[TaintFact],
        out: set[TaintFact],
        aliases: AliasGroups,
    ) -> None:
        """Default taint wrapper for calls with no analyzable body."""
        triggering: list[TaintFact] = []
        for arg in stmt.args:
            if not is_constant_value(arg):
                triggering.extend(self._facts_on(facts, arg, aliases))
        if stmt.receiver:
            triggering.extend(self._facts_on(facts, stmt.receiver, aliases))
        if not triggering:
            return
        sources = {f.source for f in triggering}
        for src in sources:
            if stmt.lhs:
                self._add_fact(out, TaintFact(AccessPath(stmt.lhs, ()), src), aliases)
            if stmt.receiver:
                self._add_fact(
                    out, TaintFact(AccessPath(stmt.receiver, ()), src), aliases
                )

    # -- leaks ------------------------------------------------------------

    def _record_leak(self, leak: TaintLeak) -> None:
        if leak.key() not in self._leak_keys:
            self._leak_keys.add(leak.key())
            self.leaks.append(leak)


# ---------------------------------------------------------------------------
# Evaluation driver
# ---------------------------------------------------------------------------


@dataclass
class BenchmarkEvaluation:
    name: str
    expected: int
    detected: int
    true_positives: int
    false_positives: int
    missed: int
    leaks: list[TaintLeak]
    facts_generated: int
    methods_analyzed: int


def match_leaks(program: Program, leaks: list[TaintLeak]) -> tuple[int, int, int]:
    """Match detected leaks against ``expected_leaks`` by source/sink methods."""
    matched_expected: set[int] = set()
    true_positives = 0
    for leak in leaks:
        hit = None
        for i, exp in enumerate(program.expected_leaks):
            if (
                exp.get("source_method") == leak.source_method
                and exp.get("sink_method") == leak.sink_method
            ):
                hit = i
                break
        if hit is not None:
            matched_expected.add(hit)
            true_positives += 1
    false_positives = len(leaks) - true_positives
    missed = len(program.expected_leaks) - len(matched_expected)
    return true_positives, false_positives, missed


def evaluate_program(program: Program) -> BenchmarkEvaluation:
    analysis = IFDSTaintAnalysis(program).run()
    tp, fp, missed = match_leaks(program, analysis.leaks)
    return BenchmarkEvaluation(
        name=program.name,
        expected=len(program.expected_leaks),
        detected=len(analysis.leaks),
        true_positives=tp,
        false_positives=fp,
        missed=missed,
        leaks=analysis.leaks,
        facts_generated=analysis.facts_generated,
        methods_analyzed=analysis.methods_analyzed,
    )


def print_evaluation(ev: BenchmarkEvaluation) -> None:
    print(f"BENCHMARK: {ev.name}")
    print(f"EXPECTED_LEAKS: {ev.expected}")
    print(f"DETECTED_LEAKS: {ev.detected}")
    print(f"TRUE_POSITIVES: {ev.true_positives}")
    print(f"FALSE_POSITIVES: {ev.false_positives}")
    print(f"MISSED_LEAKS: {ev.missed}")
    print(f"TAINT_FACTS_GENERATED: {ev.facts_generated}")
    print(f"METHODS_ANALYZED: {ev.methods_analyzed}")
    for leak in ev.leaks:
        print(
            "LEAK: "
            f"{leak.source_method}({leak.source_category}) -> "
            f"{leak.sink_method}({leak.sink_category}) "
            f"via {leak.tainted_var} at stmt {leak.sink_stmt_id}"
        )


def main(argv: list[str]) -> int:
    benchmark_dir = argv[1] if len(argv) > 1 else "benchmarks"
    programs = load_all_benchmarks(benchmark_dir)

    print("LAYER: flowdroid")
    total_expected = total_detected = total_tp = total_fp = total_missed = 0
    total_facts = total_methods = 0
    with Timer() as timer:
        for program in programs:
            ev = evaluate_program(program)
            print_evaluation(ev)
            total_expected += ev.expected
            total_detected += ev.detected
            total_tp += ev.true_positives
            total_fp += ev.false_positives
            total_missed += ev.missed
            total_facts += ev.facts_generated
            total_methods += ev.methods_analyzed

    precision = total_tp / total_detected if total_detected else 1.0
    recall = total_tp / total_expected if total_expected else 1.0
    f1 = (
        2 * precision * recall / (precision + recall)
        if precision + recall
        else 0.0
    )
    print(f"TOTAL_BENCHMARKS: {len(programs)}")
    print(f"TOTAL_EXPECTED_LEAKS: {total_expected}")
    print(f"TOTAL_DETECTED_LEAKS: {total_detected}")
    print(f"TOTAL_TRUE_POSITIVES: {total_tp}")
    print(f"TOTAL_FALSE_POSITIVES: {total_fp}")
    print(f"TOTAL_MISSED_LEAKS: {total_missed}")
    print(f"TOTAL_TAINT_FACTS: {total_facts}")
    print(f"TOTAL_METHODS_ANALYZED: {total_methods}")
    print(f"PRECISION: {precision:.4f}")
    print(f"RECALL: {recall:.4f}")
    print(f"F1: {f1:.4f}")
    print(f"ANALYSIS_TIME_MS: {timer.elapsed_ms:.2f}")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

