"""
stubdroid_analysis.py -- StubDroid-style library summaries.

Layer 3 of the static-analysis stack, built on top of the FlowDroid
layer (:mod:`flowdroid_analysis`). Provides:

* automatic library-summary generation (:class:`SummaryGenerator`):
  every library method with a body is analyzed once, symbolically, to
  derive explicit dataflow summaries (:class:`MethodSummary`) of the
  form ``parameter i -> this.f``, ``this.f -> return`` etc.,
* a summary-aware taint wrapper (:class:`StubDroidAnalysis`) that
  applies these summaries at call sites instead of the coarse default
  taint wrapper, yielding precise field-level taint propagation
  through library containers such as ``java.util.ArrayList`` and
  ``java.util.HashMap``.

Runs standalone::

    python3 stubdroid_analysis.py [benchmark_dir]

and emits ``KEY: VALUE`` experiment lines covering summary generation
and the summary-aware taint analysis per benchmark plus aggregates.
"""

from __future__ import annotations

import sys
from dataclasses import dataclass, field

from flowdroid_analysis import (
    AccessPath,
    AliasGroups,
    BenchmarkEvaluation,
    IFDSTaintAnalysis,
    SourceInfo,
    TaintFact,
    TaintLeak,
    match_leaks,
    print_evaluation,
)
from program_model import ClassDef, Method, Program, Statement, load_all_benchmarks
from soot_analysis import Scene, is_constant_value
from utils import Timer


# ---------------------------------------------------------------------------
# Summaries
# ---------------------------------------------------------------------------


@dataclass(frozen=True)
class SummaryEndpoint:
    """One end of a summary flow: this, a parameter, or the return value."""

    kind: str  # "this" | "param" | "return"
    index: int = -1
    fields: tuple[str, ...] = ()

    def __str__(self) -> str:
        if self.kind == "this":
            base = "this"
        elif self.kind == "param":
            base = f"@parameter{self.index}"
        else:
            base = "@return"
        if self.fields:
            return base + "." + ".".join(self.fields)
        return base


THIS = SummaryEndpoint("this")
RETURN = SummaryEndpoint("return")


@dataclass
class MethodSummary:
    """Explicit dataflow summary of one library method."""

    signature: str
    flows: frozenset[tuple[SummaryEndpoint, SummaryEndpoint]] = frozenset()

    def __str__(self) -> str:
        body = ", ".join(f"{s} -> {d}" for s, d in sorted(self.flows, key=str))
        return f"{self.signature}: {body}"


class SummaryGenerator:
    """Derives StubDroid-style summaries from library method bodies.

    Each method is analyzed symbolically: `this`, every declared field
    of `this`, and every parameter are seeded with unique labels, and
    the labels are propagated through the body. Labels reaching a field
    of `this` or the return value become summary flows.
    """

    def __init__(self, scene: Scene):
        self.scene = scene
        self.methods_analyzed = 0

    def generate_for_program(self) -> dict[str, MethodSummary]:
        summaries: dict[str, MethodSummary] = {}
        for cls in self.scene.classes.values():
            if not cls.is_library:
                continue
            for method in cls.methods:
                if method.body is None:
                    continue
                summary = self.generate_for_method(cls, method)
                summaries[summary.signature] = summary
        return summaries

    def generate_for_method(self, cls: ClassDef, method: Method) -> MethodSummary:
        body = method.body
        sig = method.signature.full_signature()
        self.methods_analyzed += 1

        this_local = body.this_local
        local_labels: dict[str, set[SummaryEndpoint]] = {}
        field_labels: dict[str, set[SummaryEndpoint]] = {}
        if this_local:
            local_labels[this_local] = {THIS}
        for i, param in enumerate(body.param_locals):
            local_labels[param] = {SummaryEndpoint("param", i)}
        for f in cls.fields:
            fname = f["name"] if isinstance(f, dict) else f.name
            field_labels.setdefault(fname, set()).add(SummaryEndpoint("this", -1, (fname,)))

        statements = body.statements
        for _ in range(len(statements) * 3 + 10):
            changed = False
            for stmt in statements:
                changed |= self._transfer(stmt, this_local, local_labels, field_labels)
            if not changed:
                break

        flows: set[tuple[SummaryEndpoint, SummaryEndpoint]] = set()
        for fname, seeds in field_labels.items():
            dst = SummaryEndpoint("this", -1, (fname,))
            for seed in seeds:
                if seed != dst:
                    flows.add((seed, dst))
        for stmt in statements:
            if stmt.kind == "return" and stmt.rhs and not is_constant_value(stmt.rhs):
                for seed in local_labels.get(stmt.rhs, ()):
                    flows.add((seed, RETURN))
        return MethodSummary(sig, frozenset(flows))

    @staticmethod
    def _identity_seed(stmt: Statement) -> SummaryEndpoint | None:
        if stmt.rhs == "@this":
            return THIS
        if stmt.rhs and stmt.rhs.startswith("@parameter"):
            try:
                return SummaryEndpoint("param", int(stmt.rhs[len("@parameter"):]))
            except ValueError:
                return None
        return None

    def _transfer(
        self,
        stmt: Statement,
        this_local: str | None,
        local_labels: dict[str, set[SummaryEndpoint]],
        field_labels: dict[str, set[SummaryEndpoint]],
    ) -> bool:
        def put(labels: dict, key, values: set) -> bool:
            before = len(labels.get(key, ()))
            if not values:
                return False
            new = labels.setdefault(key, set()) | values
            labels[key] = new
            return len(new) != before

        if stmt.kind == "identity" and stmt.lhs:
            seed = self._identity_seed(stmt)
            return put(local_labels, stmt.lhs, {seed} if seed else set())
        if stmt.kind == "assign" and stmt.lhs:
            if stmt.rhs and not is_constant_value(stmt.rhs):
                return put(local_labels, stmt.lhs, set(local_labels.get(stmt.rhs, ())))
            return False
        if stmt.kind == "field_store" and stmt.field_ref is not None:
            ref = stmt.field_ref
            if ref.base == this_local:
                stored = [v for v in stmt.rhs_vars if not is_constant_value(v)]
                if stored:
                    return put(
                        field_labels, ref.field_name,
                        set(local_labels.get(stored[0], ())),
                    )
            return False
        if stmt.kind == "field_load" and stmt.field_ref is not None and stmt.lhs:
            ref = stmt.field_ref
            if ref.base == this_local:
                return put(local_labels, stmt.lhs, set(field_labels.get(ref.field_name, ())))
            return put(local_labels, stmt.lhs, set(local_labels.get(ref.base, ())))
        if stmt.kind == "call":
            merged: set[SummaryEndpoint] = set()
            if stmt.receiver:
                merged |= local_labels.get(stmt.receiver, set())
            for arg in stmt.args:
                if not is_constant_value(arg):
                    merged |= local_labels.get(arg, set())
            changed = False
            if stmt.lhs:
                changed |= put(local_labels, stmt.lhs, merged)
            if stmt.receiver:
                arg_labels: set[SummaryEndpoint] = set()
                for arg in stmt.args:
                    if not is_constant_value(arg):
                        arg_labels |= local_labels.get(arg, set())
                changed |= put(local_labels, stmt.receiver, arg_labels)
            return changed
        return False


# ---------------------------------------------------------------------------
# Summary-aware taint analysis
# ---------------------------------------------------------------------------


class StubDroidAnalysis(IFDSTaintAnalysis):
    """IFDS taint analysis that applies library summaries at call sites."""

    def __init__(self, program: Program, summaries: dict[str, MethodSummary]):
        super().__init__(program)
        self.summaries = summaries
        self.summary_applications = 0

    def _apply_opaque_call(
        self,
        stmt: Statement,
        facts: set[TaintFact],
        out: set[TaintFact],
        aliases: AliasGroups,
    ) -> None:
        summary = self._summary_for(stmt)
        if summary is None:
            super()._apply_opaque_call(stmt, facts, out, aliases)
            return
        self.summary_applications += 1
        self._apply_summary(summary, stmt, facts, out, aliases)

    def _summary_for(self, stmt: Statement) -> MethodSummary | None:
        if stmt.callee is None:
            return None
        summary = self.summaries.get(stmt.callee.full_signature())
        if summary is not None:
            return summary
        for target in self.scene.resolve_cha(stmt.callee):
            summary = self.summaries.get(target.signature.full_signature())
            if summary is not None:
                return summary
        return None

    @staticmethod
    def _fields_match(fact_fields: tuple[str, ...], src_fields: tuple[str, ...]) -> bool:
        if not src_fields:
            return True  # whole-endpoint taint: any taint on it flows
        if not fact_fields:
            return True  # whole object tainted covers any of its fields
        return fact_fields[: len(src_fields)] == src_fields

    def _apply_summary(
        self,
        summary: MethodSummary,
        stmt: Statement,
        facts: set[TaintFact],
        out: set[TaintFact],
        aliases: AliasGroups,
    ) -> None:
        for src, dst in summary.flows:
            if src.kind == "param":
                if src.index >= len(stmt.args):
                    continue
                actual = stmt.args[src.index]
            elif src.kind == "this":
                actual = stmt.receiver
            else:
                continue
            if actual is None or is_constant_value(actual):
                continue
            for fact in self._facts_on(facts, actual, aliases):
                if not self._fields_match(fact.path.fields, src.fields):
                    continue
                if dst.kind == "return" and stmt.lhs:
                    self._add_fact(
                        out, TaintFact(AccessPath(stmt.lhs, ()), fact.source), aliases
                    )
                elif dst.kind == "this" and stmt.receiver:
                    self._add_fact(
                        out,
                        TaintFact(AccessPath(stmt.receiver, dst.fields), fact.source),
                        aliases,
                    )


# ---------------------------------------------------------------------------
# Evaluation driver
# ---------------------------------------------------------------------------


def evaluate_program_with_summaries(
    program: Program,
) -> tuple[BenchmarkEvaluation, dict[str, MethodSummary], int, int]:
    scene = Scene().load_program(program)
    generator = SummaryGenerator(scene)
    summaries = generator.generate_for_program()
    analysis = StubDroidAnalysis(program, summaries).run()
    tp, fp, missed = match_leaks(program, analysis.leaks)
    evaluation = BenchmarkEvaluation(
        name=program.name,
        expected=len(program.expected_leaks),
        detected=len(analysis.leaks),
        true_positives=tp,
        false_positives=fp,
        missed=missed,
        leaks=analysis.leaks,
        facts_generated=analysis.facts_generated,
        methods_analyzed=analysis.methods_analyzed,
    )
    return evaluation, summaries, generator.methods_analyzed, analysis.summary_applications


def main(argv: list[str]) -> int:
    benchmark_dir = argv[1] if len(argv) > 1 else "benchmarks"
    programs = load_all_benchmarks(benchmark_dir)

    print("LAYER: stubdroid")
    total_expected = total_detected = total_tp = total_fp = total_missed = 0
    total_methods = total_summaries = total_applications = 0
    with Timer() as timer:
        for program in programs:
            ev, summaries, methods_analyzed, applications = (
                evaluate_program_with_summaries(program)
            )
            nonempty = sum(1 for s in summaries.values() if s.flows)
            print_evaluation(ev)
            print(f"LIBRARY_METHODS_ANALYZED: {methods_analyzed}")
            print(f"SUMMARIES_GENERATED: {nonempty}")
            print(f"SUMMARY_APPLICATIONS: {applications}")
            for summary in sorted(summaries.values(), key=lambda s: s.signature):
                if summary.flows:
                    print(f"SUMMARY: {summary}")
            total_expected += ev.expected
            total_detected += ev.detected
            total_tp += ev.true_positives
            total_fp += ev.false_positives
            total_missed += ev.missed
            total_methods += methods_analyzed
            total_summaries += nonempty
            total_applications += applications

    precision = total_tp / total_detected if total_detected else 1.0
    recall = total_tp / total_expected if total_expected else 1.0
    f1 = 2 * precision * recall / (precision + recall) if precision + recall else 0.0
    print(f"TOTAL_BENCHMARKS: {len(programs)}")
    print(f"TOTAL_EXPECTED_LEAKS: {total_expected}")
    print(f"TOTAL_DETECTED_LEAKS: {total_detected}")
    print(f"TOTAL_TRUE_POSITIVES: {total_tp}")
    print(f"TOTAL_FALSE_POSITIVES: {total_fp}")
    print(f"TOTAL_MISSED_LEAKS: {total_missed}")
    print(f"TOTAL_LIBRARY_METHODS_ANALYZED: {total_methods}")
    print(f"TOTAL_SUMMARIES_GENERATED: {total_summaries}")
    print(f"TOTAL_SUMMARY_APPLICATIONS: {total_applications}")
    print(f"PRECISION: {precision:.4f}")
    print(f"RECALL: {recall:.4f}")
    print(f"F1: {f1:.4f}")
    print(f"ALL_EXPECTED_LEAKS_FOUND: {str(total_missed == 0).lower()}")
    print(f"ANALYSIS_TIME_MS: {timer.elapsed_ms:.2f}")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

